        dict(page=361,source_id='ASTRA-V-POLYNOMES-361;check/findings/findings_361_365.json#1',English_rendering='polynomials; necessary',decision='Both French polynomes/polynômes repairs and nécéssaire/nécessaire have unchanged English renderings. The forward derivative coefficient maps and reverse exponential coefficient maps are identical in the two source forms.'),
        dict(page=361,source_id='review/expose_v/page_status.jsonl#pages357-361',English_rendering='five complete source pages,ten native targets,and no author notes',decision='All prose,formulas,underline spans and placement were manually compared with both reviewed source forms. Five boundary dispositions are separately recorded. No image review or PDF rendering is newly claimed by this translation pass;there are no original author notes or macro continuation blocks in this batch.')
